{
  "extractions": [
    {
      "unit": "F001",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "29 CFR 1910.165 applies to all emergency employee alarms installed to meet a particular OSHA standard, but does not apply to those discharge or supervisory alarms required on various fixed extinguishing systems or to supervisory alarms on fire suppression, alarm or detection systems unless they are intended to be employee alarm systems.",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The requirements in 29 CFR 1910.165 that pertain to maintenance, testing and inspection shall apply to all local fire alarm signaling systems used for alerting employees regardless of the other functions of the system.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "All pre-discharge employee alarms installed to meet a particular OSHA standard shall meet the requirements of paragraphs (b)(1) through (4), (c), and (d)(1) of 29 CFR 1910.165.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall",
        "references": [
          "paragraphs (b)(1) through (4)",
          "(c)",
          "(d)(1)"
        ]
      }
    },
    {
      "unit": "F004",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The employee alarm system shall provide warning for necessary emergency action as called for in the emergency action plan, or for reaction time for safe escape of employees from the workplace or the immediate work area, or both.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F005",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The employee alarm shall be capable of being perceived above ambient noise or light levels by all employees in the affected portions of the workplace.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F005",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "Tactile devices may be used to alert those employees who would not otherwise be able to recognize the audible or visual alarm.",
        "kind": "permission",
        "modality": "may",
        "modality_quote": "may"
      }
    },
    {
      "unit": "F006",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The employee alarm shall be distinctive and recognizable as a signal to evacuate the work area or to perform actions designated under the emergency action plan.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The employer shall explain to each employee the preferred means of reporting emergencies, such as manual pull box alarms, public address systems, radio or telephones.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The employer shall post emergency telephone numbers near telephones, or employee notice boards, and other conspicuous locations when telephones serve as a means of reporting emergencies.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "Where a communication system also serves as the employee alarm system, all emergency messages shall have priority over all non-emergency messages.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F008",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The employer shall establish procedures for sounding emergency alarms in the workplace.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F008",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "For those employers with 10 or fewer employees in a particular workplace, direct voice communication is an acceptable procedure for sounding the alarm provided all employees can hear the alarm.",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F008",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "Workplaces with 10 or fewer employees where direct voice communication is used need not have a back-up system.",
        "kind": "exemption",
        "modality": "not_required",
        "modality_quote": "need not"
      }
    },
    {
      "unit": "F009",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The employer shall assure that all devices, components, combinations of devices or systems constructed and installed to comply with 29 CFR 1910.165 are approved.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F009",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "Steam whistles, air horns, strobe lights or similar lighting devices, or tactile devices meeting the requirements of 29 CFR 1910.165 are considered to meet the requirement for approval.",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F010",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The employer shall assure that all employee alarm systems are restored to normal operating condition as promptly as possible after each test or alarm.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F010",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "Spare alarm devices and components subject to wear or destruction shall be available in sufficient quantities and locations for prompt restoration of the system.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F011",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The employer shall assure that all employee alarm systems are maintained in operating condition except when undergoing repairs or maintenance.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F012",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The employer shall assure that a test of the reliability and adequacy of non-supervised employee alarm systems is made every two months.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F012",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "A different actuation device shall be used in each test of a multi-actuation device system so that no individual device is used for two consecutive tests.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F013",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The employer shall maintain or replace power supplies as often as is necessary to assure a fully operational condition.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F013",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "Back-up means of alarm, such as employee runners or telephones, shall be provided when systems are out of service.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F014",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The employer shall assure that employee alarm circuitry installed after January 1, 1981, which is capable of being supervised is supervised and that it will provide positive notification to assigned personnel whenever a deficiency exists in the system.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F014",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The employer shall assure that all supervised employee alarm systems are tested at least annually for reliability and adequacy.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F015",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The employer shall assure that the servicing, maintenance and testing of employee alarms are done by persons trained in the designed operation and functions necessary for reliable and safe operation of the system.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F016",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The employer shall assure that manually operated actuation devices for use in conjunction with employee alarms are unobstructed, conspicuous and readily accessible.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    }
  ]
}
